from pathlib import Path
import shlex
base = Path('/project')
deps = {}
for line in (base / 'deps.txt').read_text().splitlines():
    if not line.strip():
        continue
    target, sep, rest = line.partition(':')
    if not sep or not target.strip():
        raise ValueError(f'Invalid dependency line: {line!r}')
    deps[target.strip()] = rest.split()
order = []
state = {}
def visit(target):
    if state.get(target) == 1:
        raise ValueError(f'Dependency cycle at {target}')
    if state.get(target) == 2:
        return
    if target not in deps:
        raise ValueError(f'Undefined target: {target}')
    if '/' in target or target in ('.', '..'):
        raise ValueError(f'Invalid target filename: {target}')
    state[target] = 1
    for dep in deps[target]:
        visit(dep)
    state[target] = 2
    order.append(target)
for target in deps:
    visit(target)
lines = ['#!/bin/bash', 'set -euo pipefail', 'mkdir -p /project/out']
for target in order:
    lines.append("printf '%s\\n' " + shlex.quote('built: ' + target) + ' > ' + shlex.quote('/project/out/' + target))
    lines.append("printf '%s\\n' " + shlex.quote(target))
(base / 'build.sh').write_text('\n'.join(lines) + '\n')
